package nl.tankarena.ui.compose.legacy

import androidx.compose.ui.graphics.ImageBitmap
import androidx.compose.ui.graphics.asComposeImageBitmap
import java.util.Base64
import org.jetbrains.skia.Bitmap
import org.jetbrains.skia.ColorAlphaType
import org.jetbrains.skia.ColorType
import org.jetbrains.skia.ImageInfo

/** The original's fonts and game palette (generated by `mapconv extract-fonts`). */
object LegacyFonts {
    private val decoder = Base64.getDecoder()

    /** src/graph/5x5font.s: five rows per character, bit 7 leftmost. */
    val small: ByteArray = decoder.decode(GeneratedLegacyFonts.FONT_5X5)

    /** `big_font`, SETUP_FONT of DATA/SETSOUND.DAT: 8×16 glyphs for characters 32..255. */
    val big: ByteArray = decoder.decode(GeneratedLegacyFonts.BIG_FONT)

    /** DATA/PALETTE.DAT as 0xRRGGBB. */
    val gamePalette: IntArray = decoder.decode(GeneratedLegacyFonts.PALETTE).let { rgb ->
        IntArray(256) { i -> ((rgb[i * 3].toInt() and 0xFF) shl 16) or ((rgb[i * 3 + 1].toInt() and 0xFF) shl 8) or (rgb[i * 3 + 2].toInt() and 0xFF) }
    }

    /** Legacy `big_height`, `text_height(big_font)`. */
    const val BIG_HEIGHT = 16
    const val BIG_WIDTH = 8
    const val BIG_FIRST = 32

    /** `_write_text`: every character takes 6 pixels across. */
    const val SMALL_PITCH = 6
}

/** An 8-bit picture: palette indices and the picture's own palette (0xRRGGBB). */
class IndexedBitmap(val width: Int, val height: Int, val pixels: ByteArray, val palette: IntArray) {
    operator fun get(x: Int, y: Int): Int = pixels[x + y * width].toInt() and 0xFF

    companion object {
        /** An uncompressed 8-bit Windows BMP, as extracted from DATA/BITMAPS.DAT. */
        fun readBmp(bytes: ByteArray): IndexedBitmap {
            fun int(at: Int) = (bytes[at].toInt() and 0xFF) or ((bytes[at + 1].toInt() and 0xFF) shl 8) or
                ((bytes[at + 2].toInt() and 0xFF) shl 16) or ((bytes[at + 3].toInt() and 0xFF) shl 24)
            fun short(at: Int) = (bytes[at].toInt() and 0xFF) or ((bytes[at + 1].toInt() and 0xFF) shl 8)
            require(bytes[0] == 'B'.code.toByte() && bytes[1] == 'M'.code.toByte()) { "not a BMP" }
            val offset = int(10)
            val headerSize = int(14)
            val width = int(18)
            val rawHeight = int(22)
            require(short(28) == 8 && int(30) == 0) { "only uncompressed 8-bit BMPs are supported" }
            val height = kotlin.math.abs(rawHeight)
            val paletteAt = 14 + headerSize
            val palette = IntArray(256) { i ->
                val at = paletteAt + i * 4
                if (at + 2 >= offset) 0 else ((bytes[at + 2].toInt() and 0xFF) shl 16) or ((bytes[at + 1].toInt() and 0xFF) shl 8) or (bytes[at].toInt() and 0xFF)
            }
            val stride = (width + 3) and 3.inv()
            val pixels = ByteArray(width * height)
            for (y in 0 until height) {
                val row = if (rawHeight > 0) height - 1 - y else y
                System.arraycopy(bytes, offset + row * stride, pixels, y * width, width)
            }
            return IndexedBitmap(width, height, pixels, palette)
        }

        /** A picture extracted from `DATA/BITMAPS.DAT` (the panel tile, the `BLACK*.BMP` backdrops), bundled as `backgrounds/`. */
        fun loadBackground(fileName: String): IndexedBitmap? {
            val bytes = readBackground(fileName) ?: return null
            return runCatching { readBmp(bytes) }.getOrNull()
        }

        val panel: IndexedBitmap? by lazy { loadBackground("panel.bmp") }
    }
}

/**
 * The 320×200 VGA mode 13h screen of the menus, prompts and text pages: palette indices drawn
 * with ports of the original's routines (src/graph/mode13.c, 5x5text.c, prompt.c, Allegro's
 * textout), then shown through a palette.
 */
class Mode13Screen {
    val pixels = ByteArray(WIDTH * HEIGHT)

    /** Legacy `write_panel()`: the 40×40 panel tile across the screen. */
    fun panel() {
        val tile = IndexedBitmap.panel ?: return
        for (y in 0 until HEIGHT) for (x in 0 until WIDTH) {
            pixels[x + y * WIDTH] = tile[x % tile.width, y % tile.height].toByte()
        }
    }

    /** Legacy `blit(bmp, screen, 0, 0, x, y, ...)`. */
    fun blit(picture: IndexedBitmap, x: Int = 0, y: Int = 0) {
        for (py in 0 until picture.height) for (px in 0 until picture.width) {
            set(x + px, y + py, picture[px, py])
        }
    }

    /** Legacy `m13_bar()`: a filled rectangle of [color]. */
    fun bar(x: Int, y: Int, width: Int, height: Int, color: Int) {
        for (py in y until y + height) for (px in x until x + width) set(px, py, color)
    }

    /** Legacy `m13_add_bar()`: adds [amount] to every palette index in the rectangle. */
    fun addBar(x: Int, y: Int, width: Int, height: Int, amount: Int) {
        for (py in y until y + height) for (px in x until x + width) {
            if (px in 0 until WIDTH && py in 0 until HEIGHT) set(px, py, (get(px, py) + amount) and 0xFF)
        }
    }

    /** Legacy `m13_write_text()`: the 5×5 font, only the set pixels; returns the width drawn. */
    fun writeText(x: Int, y: Int, color: Int, text: String): Int = smallText(x, y, color, text, background = null)

    /** Legacy `m13_overwrite_text()`: the 5×5 font on black cells 6 pixels wide. */
    fun overwriteText(x: Int, y: Int, color: Int, text: String): Int = smallText(x, y, color, text, background = 0)

    private fun smallText(x: Int, y: Int, color: Int, text: String, background: Int?): Int {
        // _write_text: nothing is drawn on the last rows, and characters past the edge are skipped.
        if (y < 0 || y >= HEIGHT - 5) return text.length * LegacyFonts.SMALL_PITCH
        var cx = x
        for (char in text) {
            if (cx >= 0 && cx < WIDTH - 6) {
                val code = char.code
                for (row in 0 until 5) {
                    val bits = if (code < 128) LegacyFonts.small[code * 5 + row].toInt() else 0
                    for (column in 0 until 6) {
                        val on = bits and (0x80 ushr column) != 0
                        if (on) set(cx + column, y + row, color) else if (background != null) set(cx + column, y + row, background)
                    }
                }
            }
            cx += LegacyFonts.SMALL_PITCH
        }
        return text.length * LegacyFonts.SMALL_PITCH
    }

    /** Allegro `textout_centre(screen, big_font, text, x, y, color)`. */
    fun bigTextCentre(text: String, centreX: Int, y: Int, color: Int) {
        bigText(text, centreX - bigLength(text) / 2, y, color)
    }

    /** Allegro `textout(screen, big_font, ...)`: the set pixels of each 8×16 glyph in [color]. */
    fun bigText(text: String, x: Int, y: Int, color: Int) {
        var cx = x
        for (char in text) {
            val glyph = char.code - LegacyFonts.BIG_FIRST
            if (glyph in 0 until LegacyFonts.big.size / LegacyFonts.BIG_HEIGHT) {
                for (row in 0 until LegacyFonts.BIG_HEIGHT) {
                    val bits = LegacyFonts.big[glyph * LegacyFonts.BIG_HEIGHT + row].toInt()
                    for (column in 0 until LegacyFonts.BIG_WIDTH) {
                        if (bits and (0x80 ushr column) != 0) set(cx + column, y + row, color)
                    }
                }
            }
            cx += LegacyFonts.BIG_WIDTH
        }
    }

    operator fun get(x: Int, y: Int): Int = pixels[x + y * WIDTH].toInt() and 0xFF

    fun set(x: Int, y: Int, color: Int) {
        if (x in 0 until WIDTH && y in 0 until HEIGHT) pixels[x + y * WIDTH] = color.toByte()
    }

    /** The screen through [palette] (0xRRGGBB per index). */
    fun toImageBitmap(palette: IntArray): ImageBitmap {
        val bytes = ByteArray(WIDTH * HEIGHT * 4)
        for (i in 0 until WIDTH * HEIGHT) {
            val rgb = palette[pixels[i].toInt() and 0xFF]
            bytes[i * 4] = rgb.toByte()
            bytes[i * 4 + 1] = (rgb ushr 8).toByte()
            bytes[i * 4 + 2] = (rgb ushr 16).toByte()
            bytes[i * 4 + 3] = 0xFF.toByte()
        }
        val bitmap = Bitmap()
        bitmap.allocPixels(ImageInfo(WIDTH, HEIGHT, ColorType.BGRA_8888, ColorAlphaType.OPAQUE))
        bitmap.installPixels(bytes)
        return bitmap.asComposeImageBitmap()
    }

    companion object {
        const val WIDTH = 320
        const val HEIGHT = 200

        /** Legacy `text_length(big_font, text)`: every glyph is 8 wide. */
        fun bigLength(text: String): Int = text.length * LegacyFonts.BIG_WIDTH
    }
}

/** The bytes of a picture bundled under `backgrounds/` (see [IndexedBitmap.loadBackground]), or null. */
internal fun readBackground(fileName: String): ByteArray? =
    IndexedBitmap::class.java.classLoader.getResourceAsStream("backgrounds/$fileName")?.use { it.readBytes() }
